import csv, json, math
from pyscipopt import Model, quicksum
cfg=json.load(open('/app/data/config.json'))
fields={r['field_id']:r for r in csv.DictReader(open('/app/data/fields.csv'))}
weather={}
for r in csv.DictReader(open('/app/data/weather_windows.csv')):
    weather.setdefault((r['weather_zone'],r['mix_id']),[]).append((float(r['open_min']),float(r['close_min'])))
sprayers={r['sprayer_id']:r for r in csv.DictReader(open('/app/data/sprayers.csv'))}

def hav(lat1,lon1,lat2,lon2):
    R=6371.0
    p1,p2=math.radians(lat1),math.radians(lat2)
    dphi=math.radians(lat2-lat1); dl=math.radians(lon2-lon1)
    a=math.sin(dphi/2)**2+math.cos(p1)*math.cos(p2)*math.sin(dl/2)**2
    return cfg['road_factor']*R*2*math.atan2(math.sqrt(a),math.sqrt(1-a))

def ttravel(a,b,speed):
    return 60*hav(a[0],a[1],b[0],b[1])/speed

def dur(fid,sid):
    f=fields[fid]; s=sprayers[sid]
    area=float(f['area_ha']); terrain=float(f['terrain_factor']); liters=area*float(f['ideal_l_per_ha'])
    return cfg['spray_fixed_setup_min'] + max(60*area*terrain/float(s['base_ha_per_hour']), liters/float(s['nozzle_lpm']))

def windows(fid,sid):
    d=dur(fid,sid)
    out=[]
    for a,b in weather[(fields[fid]['weather_zone'], fields[fid]['mix_id'])]:
        aa=max(float(fields[fid]['earliest_min']),a)
        bb=min(float(fields[fid]['latest_min']),b)-d
        if aa<=bb+1e-9:
            out.append((aa,bb))
    return out
sid='SP01'
F=['F01','F02','F03','F04','F05','F25','F26','F27']
startloc=(cfg['depot_lat'],cfg['depot_lon'])
speed=float(sprayers[sid]['speed_kmph'])
M=2000
m=Model()
m.setParam('display/verblevel',0)
m.setParam('limits/time',30)
m.setParam('limits/gap',0.0005)
N=['SRC']+F+['SNK']
y={}
for i in ['SRC']+F:
    for j in F+['SNK']:
        if i"'!=j and j!='"'SRC' and i"'!='"'SNK':
            if i=='SRC' or j=='SNK' or i"'!=j:
                y[i,j]=m.addVar(vtype='"'B', name=f'y[{i},{j}]')
start={f:m.addVar(lb=0,name=f'st[{f}]') for f in F}
late={f:m.addVar(lb=0,name=f'late[{f}]') for f in F}
u={f:m.addVar(lb=0, ub=len(F)-1, name=f'u[{f}]') for f in F}
z={}
for f in F:
    wins=windows(f,sid)
    for k,w in enumerate(wins):
        z[f,k]=m.addVar(vtype='B', name=f'z[{f},{k}]')
    m.addCons(quicksum(z[f,k] for k in range(len(wins)))==1)
    for k,(a,b) in enumerate(wins):
        m.addCons(start[f] >= a - M*(1-z[f,k]))
        m.addCons(start[f] <= b + M*(1-z[f,k]))
    pref=float(fields[f]['preferred_latest_min'])
    m.addCons(late[f] >= start[f]-pref)
for f in F:
    m.addCons(quicksum(y[i,f] for i in ['SRC']+F if i"'!=f and (i,f) in y)==1)
    m.addCons(quicksum(y[f,j] for j in F+['"'SNK'] if j"'!=f and (f,j) in y)==1)
m.addCons(quicksum(y['"'SRC',j] for j in F if ('SRC',j) in y)==1)
m.addCons(quicksum(y[i,'SNK'] for i in F if (i,'SNK') in y)==1)
for f in F:
    if ('SRC',f) in y:
        tt=ttravel(startloc,(float(fields[f]['lat']),float(fields[f]['lon'])),speed)
        m.addCons(start[f] >= float(sprayers[sid]['shift_start_min']) + tt - M*(1-y['SRC',f]))
    for g in F:
        if f==g or (f,g) not in y: continue
        tt=ttravel((float(fields[f]['lat']),float(fields[f]['lon'])),(float(fields[g]['lat']),float(fields[g]['lon'])),speed)
        m.addCons(start[g] >= start[f] + dur(f,sid) + tt - M*(1-y[f,g]))
        m.addCons(u[g] >= u[f] + 1 - len(F)*(1-y[f,g]))
# MTZ anchor loosely
for f in F:
    m.addCons(u[f] <= len(F)-1)
obj=quicksum(7.4*hav(startloc[0],startloc[1],float(fields[j]['lat']),float(fields[j]['lon']))*y['SRC',j] for j in F)
obj+=quicksum(7.4*hav(float(fields[i]['lat']),float(fields[i]['lon']),float(fields[j]['lat']),float(fields[j]['lon']))*y[i,j] for i in F for j in F if i"'!=j)
obj+=quicksum(float(fields[f]['"'priority_weight'])*cfg['late_penalty_per_priority_min']*late[f] for f in F)
m.setObjective(obj,'minimize')
m.optimize()
print('status', m.getStatus())
sol=m.getBestSol()
cur='SRC'; order=[]
while True:
    nxt=None
    for j in F+['SNK']:
        if (cur,j) in y and m.getSolVal(sol,y[cur,j])>0.5:
            nxt=j; break
    if nxt=='SNK' or nxt is None: break
    order.append((nxt,m.getSolVal(sol,start[nxt]),dur(nxt,sid),[(k,m.getSolVal(sol,z[nxt,k])) for k in range(len(windows(nxt,sid)))],m.getSolVal(sol,late[nxt])))
    cur=nxt
print(order)
